"use strict";
/* Menschen A2.1 e A2.2 (Hueber; lições 1–12 e 13–24), o livro do curso particular: o mapa de cada lição para a tela Menschen. Escrito pelo Claude
   (metas, traduções e explicações com palavras próprias; revisar com o tutor). O livro, os áudios e as transcrições ficam
   na pasta Menschen ao lado do app, fora do Git; aqui só há títulos, páginas, a lista de palavras e o que o app treina.
   Campos: n, modulo, titulo (título da lição no livro), tema, kb/ab = páginas [de, até] do Kursbuch e do Arbeitsbuch,
   gram = tópicos da Gramática do app, nota = a gramática da lição em poucas linhas, metas = “Nesta lição você consegue…”,
   palavras = [alemão, informação (artigo/plural ou Perfekt), português], faixas = [id, descrição] (kb-NN/ab-NN = arquivo NN),
   conversa = tema para a Conversa com a IA. Lição sem `metas` ainda não foi preparada.
   passos = a aula guiada da lição, na ordem das páginas do Kursbuch (menschen-aula.js): id, pag (onde está no livro), titulo,
   sobre (do que trata, com palavras próprias), quem (quem fala no áudio), faixas [[id, uso]] (uso: cena = ouvir → ler →
   ouvir de novo → repetir; repetir = palavras soltas para repetir; pausas = o próprio áudio deixa a pausa), palavras como
   acima, regra {topic, foco, visuais [{head, rows, nota}], interativo} (o mesmo formato das fichas), frases (ids do
   catalog-menschen.js) e usar {pt, ex, checks [[rótulo, regex, mínimo]]} (frase sua conferida por regra + corretor). */
const MS_B = "(?<!\\p{L})", MS_E = "(?!\\p{L})";
