const MS_REFL = ["fühl\\p{Ll}*", "gefühlt", "erinner\\p{Ll}*", "freu\\p{Ll}*", "gefreut", "ärger\\p{Ll}*", "geärgert", "streit\\p{Ll}*", "gestritten", "unterh[aä]lt\\p{Ll}*", "verst[ae]h\\p{Ll}*", "verstanden", "beschwer\\p{Ll}*", "tr[ie]ff\\p{Ll}*", "getroffen", "ruh\\p{Ll}*", "ausgeruht", "ausruh\\p{Ll}*", "verabred\\p{Ll}*", "bedank\\p{Ll}*", "entschuldig\\p{Ll}*"].map(a => "[" + a[0].toUpperCase() + a[0] + "]" + a.slice(1)).join("|");
