  refl: MS_B + "([Ff]reu|[Ää]rger|[Ii]nteressier)(e|st|t|en)" + MS_E + "[^.!?]*?" + MS_B + "(mich|dich|sich|uns|euch)" + MS_E +
    "|" + MS_B + "(mich|dich|sich|uns|euch)" + MS_E + "[^.!?]*?" + MS_B + "(ge)?([Ff]reu|[Ää]rger|[Ii]nteressier)(e|st|t|en)" + MS_E,
